const base = "http://the VM's public address:18082";
const out = {};

async function get(path) {
  const r = await fetch(base + path);
  const text = await r.text();
  return { status: r.status, body: text.slice(0, 4000), len: text.length };
}

out.v1 = await get("/v1/disbursements");
const first = await get("/v2/disbursements?limit=3");
out.v2_first = first;

// parse full first response for cursor/drained
const j = JSON.parse(first.body.length < first.len ? await (await fetch(base + "/v2/disbursements?limit=3")).text() : first.body);
out.parsed = { count: j.disbursements?.length, ids: j.disbursements?.map(d => d.id), cursor: j.cursor, drained: j.drained };

const r2 = await fetch(base + "/v2/disbursements?limit=3&cursor=" + encodeURIComponent(j.cursor));
const j2 = await r2.json();
out.parsed2 = { status: r2.status, count: j2.disbursements?.length, ids: j2.disbursements?.map(d => d.id), drained: j2.drained };

out.root = await get("/");
out.openapi = await get("/openapi.json");

return out;

